    const { tenant, limit } = request;
    if (
      typeof tenant !== 'string' ||
      tenant.length === 0 ||
      !Number.isInteger(limit) ||
      limit < 1 ||
      limit > 100
    ) {
      throw new Error('invalid request');
    }

    // Throws Error('invalid request') for a malformed cursor.
    const cursor = parseCursor(request.cursor);
    const cursorString = cursor === null ? undefined : `${cursor.createdAt}|${cursor.id}`;

