const assert = require('node:assert/strict');
const { OrderHandler } = require('../.build/handler');
const { OrderRepository } = require('../.build/repository');

const handlerFor = rows => new OrderHandler(new OrderRepository(rows));
const key = order => `${order.createdAt}|${order.id}`;

// Walk pages: ascending createdAt then lexicographic id, never repeat or skip.
{
  const rows = [
    { id: '9', tenant: 't', createdAt: '2026-01-01', total: 1 },
    { id: '10', tenant: 't', createdAt: '2026-01-01', total: 2 },
    { id: '2', tenant: 't', createdAt: '2026-01-02', total: 3 },
    { id: 'a', tenant: 't', createdAt: '2026-01-02', total: 4 },
    { id: 'b', tenant: 'u', createdAt: '2026-01-01', total: 5 },
  ];
  const handler = handlerFor(rows);
  const seen = [];
  let cursor;
  let pages = 0;
  for (;;) {
    const page = handler.list({ tenant: 't', limit: 1, cursor });
    seen.push(...page.items.map(key));
    pages++;
    if (page.nextCursor === null) break;
    assert.equal(page.nextCursor, key(page.items[page.items.length - 1]));
    cursor = page.nextCursor;
    assert.ok(pages < 10, 'pagination did not terminate');
  }
  assert.deepEqual(seen, ['2026-01-01|10', '2026-01-01|9', '2026-01-02|2', '2026-01-02|a']);
  assert.equal(pages, 4);
}

// First page without a cursor keeps filter/limit behavior; exact page is null.
{
  const rows = [
    { id: 'b', tenant: 'a', createdAt: '2026-01-02', total: 2 },
    { id: 'x', tenant: 'b', createdAt: '2026-01-01', total: 3 },
    { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 },
  ];
  const handler = handlerFor(rows);
  assert.deepEqual(handler.list({ tenant: 'a', limit: 3 }).items.map(key), ['2026-01-01|a', '2026-01-02|b']);
  assert.equal(handler.list({ tenant: 'a', limit: 3 }).nextCursor, null);
  assert.equal(handler.list({ tenant: 'a', limit: 2 }).nextCursor, null);
  assert.equal(handler.list({ tenant: 'a', limit: 1 }).nextCursor, '2026-01-01|a');
  assert.deepEqual(handler.list({ tenant: 'a', limit: 1, cursor: null }).items.map(key), ['2026-01-01|a']);
  assert.deepEqual(handler.list({ tenant: 'nobody', limit: 5 }), { items: [], nextCursor: null });
}

// Cursor resumes strictly after the pair even when its row is gone.
{
  const rows = [
    { id: 'a', tenant: 't', createdAt: '2026-01-01', total: 1 },
    { id: 'b', tenant: 't', createdAt: '2026-01-02', total: 2 },
    { id: 'c', tenant: 't', createdAt: '2026-01-03', total: 3 },
  ];
  const first = handlerFor(rows).list({ tenant: 't', limit: 1 });
  assert.equal(first.nextCursor, '2026-01-01|a');
  const deleted = rows.filter(o => o.id !== 'a');
  const next = handlerFor(deleted).list({ tenant: 't', limit: 5, cursor: first.nextCursor });
  assert.deepEqual(next.items.map(key), ['2026-01-02|b', '2026-01-03|c']);
  assert.equal(next.nextCursor, null);
  // A cursor far to the right of on-date rows also works.
  assert.deepEqual(handlerFor(rows).list({ tenant: 't', limit: 5, cursor: '2026-01-02|zzz' }).items.map(key), ['2026-01-03|c']);
}

// Filtering precedes pagination, even for a cursor pair from another tenant.
{
  const rows = [
    { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 },
    { id: 'z', tenant: 'a', createdAt: '2026-01-01', total: 2 },
    { id: 'm', tenant: 'b', createdAt: '2026-01-01', total: 3 },
  ];
  const handler = handlerFor(rows);
  assert.deepEqual(handler.list({ tenant: 'a', limit: 5, cursor: '2026-01-01|m' }).items.map(key), ['2026-01-01|z']);
  assert.deepEqual(handler.list({ tenant: 'a', limit: 5, cursor: '2026-01-01|a' }).items.map(key), ['2026-01-01|z']);
}

// Validation.
{
  const handler = handlerFor([{ id: 'a', tenant: 't', createdAt: '2026-01-01', total: 1 }]);
  for (const tenant of ['', undefined, null, 0]) {
    assert.throws(() => handler.list({ tenant, limit: 1 }), /invalid request/);
  }
  for (const limit of [0, 101, -1, 1.5, NaN, '5', Infinity, undefined]) {
    assert.throws(() => handler.list({ tenant: 't', limit }), /invalid request/);
  }
  for (const cursor of ['', 'a', 'a|', '|b', 'a|b|c', '||', 'a|b|']) {
    assert.throws(() => handler.list({ tenant: 't', limit: 1, cursor }), /invalid request/);
  }
  assert.equal(handler.list({ tenant: 't', limit: 1, cursor: '2026-01-01|a' }).items.length, 0);
  assert.equal(handler.list({ tenant: 't', limit: 100 }).items.length, 1);
}

// Repository: no mutation of the input array or rows, sorted results, optional limit.
{
  const rows = [
    { id: 'b', tenant: 't', createdAt: '2026-01-02', total: 2 },
    { id: 'a', tenant: 't', createdAt: '2026-01-01', total: 1 },
    { id: 'c', tenant: 'u', createdAt: '2026-01-01', total: 3 },
  ];
  const snapshot = JSON.parse(JSON.stringify(rows));
  const repo = new OrderRepository(rows);
  assert.deepEqual(repo.list('t').map(key), ['2026-01-01|a', '2026-01-02|b']);
  assert.deepEqual(repo.list('t', '2026-01-01|a').map(key), ['2026-01-02|b']);
  assert.deepEqual(repo.list('t', undefined, 1).map(key), ['2026-01-01|a']);
  assert.throws(() => repo.list('t', 'bad'), /invalid request/);
  assert.deepEqual(rows, snapshot);
}

console.log('cursor checks passed');
EOF
