const assert = require('node:assert/strict');
const { OrderHandler } = require('./.build/handler');
const { OrderRepository } = require('./.build/repository');
function rnd(n){ return Math.floor(Math.random()*n); }
for (let trial = 0; trial < 500; trial++) {
  const rows = [];
  const n = 1 + rnd(15);
  for (let i = 0; i < n; i++) {
    rows.push({
      id: String.fromCharCode(97 + rnd(5)) + rnd(3),
      tenant: ['a','b','c'][rnd(3)],
      createdAt: '2026-01-' + String(1 + rnd(4)).padStart(2, '0'),
      total: i
    });
  }
  const snapshot = JSON.parse(JSON.stringify(rows));
  const tenant = ['a','b','c'][rnd(3)];
  const handler = new OrderHandler(new OrderRepository(rows));
  const limit = 1 + rnd(6);
  const expected = new OrderRepository(rows).list(tenant).map(o => o.createdAt + '|' + o.id);
  const got = [];
  let cursor;
  let guard = 0;
  for (;;) {
    const page = handler.list({ tenant, limit, cursor });
    got.push(...page.items.map(o => o.createdAt + '|' + o.id));
    if (page.nextCursor === null) break;
    assert.ok(++guard < 100, 'no termination');
    cursor = page.nextCursor;
    assert.equal(cursor, got[got.length - 1]);
  }
  assert.deepEqual(got, expected, JSON.stringify({rows, tenant, limit}));
  assert.deepEqual(rows, snapshot, 'input mutated');
}
console.log('randomized pagination checks passed');
"

